            <View style={[StyleSheet.absoluteFill, styles.gate]}>
              <TokenForm rejected={rejected} />
            </View>
          ) : null}
        </View>
      </View>
    </QueryClientProvider>
  );
}

const styles = StyleSheet.create({
  page: { flex: 1, backgroundColor: '#E5E7EB', alignItems: 'center' },
