// Reproduce: claim → status page. API is mocked in the browser (no real token needed).
const { chromium } = require('playwright-core');

const BASE = process.argv[2] || 'http://localhost:8089';
const OUT = __dirname;
let claimPolls = 0;
const now = () => new Date().toISOString();
const created = now();
const claim = (status) => ({
  id: 'clm_test1', asset: 'USDT', amount: '20', fee: '1.5', receiveAmount: '18.5',
  destinationId: 'dest_wallet', status, failureReason: null, createdAt: created,
  updatedAt: status === 'pending' ? created : now(),
});

(async () => {
  const browser = await chromium.launch({ channel: 'chrome', headless: true });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  const logs = [];
  page.on('console', (m) => logs.push(`[${m.type()}] ${m.text()}`));
  page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
  await page.addInitScript(() =>
    localStorage.setItem('cashmine.token', JSON.stringify({ token: 'fake-token', rejected: false })),
  );
  await page.route('https://task-api.cashmine.io/**', async (route) => {
    const url = new URL(route.request().url());
    const method = route.request().method();
    const json = (status, body) =>
      route.fulfill({ status, contentType: 'application/json', body: JSON.stringify(body),
        headers: { 'Access-Control-Allow-Origin': '*' } });
    if (method === 'OPTIONS') return route.fulfill({ status: 204, headers: {
      'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': '*',
      'Access-Control-Allow-Methods': '*' } });
    logs.push(`[api] ${method} ${url.pathname}${url.search}`);
    if (url.pathname === '/v1/balances') return json(200, { asOf: now(), items: [
      { asset: 'USDT', decimals: 6, available: '820.413207', pending: '50.12', claiming: '0', usdPrice: '1.0002' }] });
    if (url.pathname === '/v1/claim-options') return json(200, { asset: 'USDT', minAmount: '5', fee: '1.5',
      destinations: [{ id: 'dest_wallet', label: 'Wallet 0x8f3e…a91c' }] });
    if (url.pathname === '/v1/claims' && method === 'POST') return json(201, claim('pending'));
    if (url.pathname.startsWith('/v1/claims/')) {
      claimPolls++;
      return json(200, claim(claimPolls > 3 ? 'completed' : 'pending'));
    }
    return json(404, { error: { code: 'NOT_FOUND', message: 'nope' } });
  });

